<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/config/koneksi.php';require_once dirname(__DIR__,2).'/vendor/autoload.php';use EnglAI\Learning\ReadingSessionService;
$pdo=db();$fail=[];$ok=static function(bool$c,string$m)use(&$fail){if(!$c)$fail[]=$m;};$classroom=$pdo->query("SELECT c.id FROM classrooms c JOIN classroom_lesson_plans lp ON lp.classroom_id=c.id AND lp.is_active=1 JOIN learning_activities a ON a.classroom_id=c.id AND a.lesson_plan_id=lp.id AND a.skill='reading' AND a.activity_type='standalone_question' AND a.status='ready' GROUP BY c.id HAVING COUNT(DISTINCT a.level)>=3 LIMIT 1")->fetch();if(!$classroom){fwrite(STDERR,"Multi-level Reading fixture unavailable.\n");exit(1);}$insert=$pdo->prepare("INSERT INTO classroom_members(classroom_id,session_token,display_name,avatar,membership_status,approved_at) VALUES(?,?,'Reading Level Test','reader','active',NOW())");$insert->execute([(int)$classroom['id'],hash('sha256',random_bytes(16))]);$member=(int)$pdo->lastInsertId();
try{$service=new ReadingSessionService($pdo);$availability=$service->levelAvailability((int)$classroom['id'],$member);foreach(['basic','intermediate','advanced']as$level)$ok(isset($availability[$level])&&$availability[$level]['ready']&&$availability[$level]['valid_count']>=20,"{$level} harus tersedia dari bank production.");$basic=$service->start((int)$classroom['id'],$member,'Basic');$same=$service->start((int)$classroom['id'],$member,'basic');$ok($basic===$same,'Continue Basic harus resume session yang sama.');$intermediate=$service->start((int)$classroom['id'],$member,'INTERMEDIATE');$ok($intermediate!==$basic,'Session tiap level harus terpisah.');$basicSession=$service->get($basic,$member);$intermediateSession=$service->get($intermediate,$member);$ok($basicSession['level']==='basic'&&$intermediateSession['level']==='intermediate','Session harus menyimpan canonical level.');foreach($basicSession['snapshot']['questions']as$q)$ok(($q['level']??'')==='basic','Basic session tidak boleh mengambil level lain.');ReadingSessionService::assertSnapshot($basicSession['snapshot']);$question=$service->question($basicSession);$service->beginQuestion($basic,$member);$wrong=current(array_filter(array_column($question['options'],'id'),fn($v)=>$v!==$question['correct_option_id']));$answer=$service->answer($basic,$member,$question['id'],(string)$wrong,false);$ok($answer['current_index']===1,'Wrong answer harus maju.');$resumed=$service->start((int)$classroom['id'],$member,'basic');$after=$service->get($resumed,$member);$ok($resumed===$basic&&(int)$after['current_position']===1&&(int)$after['score']===(int)$answer['score'],'Resume tidak boleh reset posisi/score.');$duplicate=$service->answer($basic,$member,$question['id'],(string)$wrong,false);$ok($duplicate['duplicate']&&$duplicate['current_index']===1,'Duplicate submission harus idempotent.');$next=$service->question($after);$service->beginQuestion($basic,$member);$timeout=$service->answer($basic,$member,$next['id'],null,true);$ok($timeout['result']==='timed_out'&&$timeout['current_index']===2,'Timeout harus maju.');$public=json_encode($service->publicState($service->get($basic,$member)));$ok(!str_contains($public,'correct_option_id')&&!str_contains($public,'explanation'),'Initial payload tidak boleh memuat answer key.');}finally{$pdo->prepare('DELETE FROM classroom_members WHERE id=?')->execute([$member]);}if($fail){fwrite(STDERR,"Reading level integration failed:\n- ".implode("\n- ",$fail)."\n");exit(1);}echo"Reading level integration OK.\n";
